-- ScholarBridgeAi — Scholarship rewrite pass 40 (Taiwan)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Taiwan is the opposite case to Norway: these three awards are real, they are institutional, and
-- they pay a monthly stipend in NT dollars on top of a tuition waiver. The error in all three rows
-- was scale - USD 2,125 to 2,250 against stipends that reach NT$30,000 to 40,000 a month.
-- Values are in TWD; amount_usd_value stays 0 for non-USD awards.

-- 632 National Cheng Kung University
UPDATE scholarships SET
  title = 'NCKU Distinguished International Student Scholarship (and VCS)',
  description = 'NCKU runs a portfolio rather than a single award, and the three parts are worth separating because they pay very differently. The NCKU Distinguished International Student Scholarship is the general one: from the 2026-27 intake NCKU states that undergraduate recipients get a tuition fee waiver plus a monthly stipend set by their college, and master''s and doctoral recipients get a waiver of full tuition including the basic credit fee plus a college-set monthly stipend. The published tiers from the preceding scheme give the shape of it - undergraduate NT$8,000 a month with a tuition waiver that excludes miscellaneous and enrolment fees, master''s NT$10,000 a month, doctoral NT$16,000 a month with a further NT$4,000 from the advisor - and the undergraduate ladder is banded, with the top 20 per cent receiving NT$15,000 and the 20 to 40 per cent band NT$10,000, plus a waiver of the basic on-campus accommodation rate. Above that sits the Veritas et Conscientia Scholarship, which is doctoral only and is the single best documented award at the university: NT$30,000 a month, made up of NT$22,000 from the university and NT$8,000 from the advisor, with tuition, credit fees and the basic dormitory rate all waived, for full-time PhD students in years one to four. There is also an Elite Doctoral Scholarship at NT$25,000 a month plus NT$8,000 from the advisor, and a Ministry of Education Elite Scholarship worth NT$300,000 a year issued as NT$25,000 a month. No separate application is filed for the Distinguished award: the international admissions committee reviews the admission documents and the award arrives with the admission letter. One exclusion matters: a student already holding a scholarship or grant for international students from a Taiwanese government agency cannot also hold this one.',
  requirements = 'Be a newly admitted international degree student at National Cheng Kung University, since the Distinguished International Student Scholarship is reviewed from the admission file and needs no separate application. Hold foreign nationality and meet NCKU international admission requirements for the chosen undergraduate, master''s or doctoral programme. Submit the admission application by the university deadline for the intake, because the award decision is mailed with the admission letter and is made for the first academic year. For the Veritas et Conscientia Scholarship, be a full-time doctoral student in years one to four and be nominated by your department or college, since that award is allocated by nomination rather than by open application. Not hold a scholarship or grant for international students from a Taiwanese government agency, which disqualifies an applicant from this award. Keep the academic standard required for renewal in later years, since continuing awards are reviewed annually.',
  coverage_type = 'Full Funding', award_basis = 'range', award_amount = 30000, award_currency = 'TWD', award_period = 'month',
  degree_levels = '["Bachelor''s","Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional scholarship with tuition waiver',
  tuition_coverage = 'A full tuition waiver including the basic credit fee, plus a monthly stipend that ranges from NT$8,000 for undergraduate recipients and NT$10,000 for master''s to NT$16,000 plus an advisor top-up for doctoral students, rising to NT$30,000 a month under the Veritas et Conscientia Scholarship with dormitory fees also waived. Amounts are set by the admitting college and reviewed annually.',
  english_requirements = 'The scholarship sets no separate English score; the English or Chinese requirement of the chosen NCKU programme applies, and most international programmes at NCKU are taught in English.',
  required_documents = '["NCKU international admission application","Academic transcripts and degree certificates","English or Chinese proficiency evidence as the programme requires","Statement of purpose and letters of recommendation","Department nomination for the Veritas et Conscientia Scholarship","No separate scholarship application for the Distinguished award"]',
  deadline = 'The award is assessed with the admission application, so the deadline is NCKU''s admission deadline for the intake',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'NCKU admits international students for the autumn and spring intakes and reviews scholarship eligibility from the admission file, so the operative date is the admission deadline published by the Office of International Affairs.',
  website_url = 'https://oia.ncku.edu.tw/p/404-1032-229890.php?Lang=en',
  source_url = 'https://oia.ncku.edu.tw/p/404-1032-229890.php?Lang=en',
  application_url = 'https://admissions.oia.ncku.edu.tw/doc/view/sn/8',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two National Cheng Kung University own pages read on 2026-10-25: the Office of International Affairs scholarships page at oia.ncku.edu.tw states that recipients of scholarships or grants for international students offered by Taiwanese government agencies are not eligible for this scholarship and must return funds if they violate the rule, that amounts are issued in New Taiwan dollars, and that from the 2026-27 intake the University Scholarship waives full tuition including the basic credit fee with a monthly stipend of maximum NT$25,000 for full-time PhD students in years 1-4, while the Distinguished International Student Scholarship gives undergraduate recipients a tuition waiver plus a college-set monthly stipend, and master and doctoral recipients a waiver of full tuition including the basic credit fee plus a college-set stipend; the same page records the preceding scheme with undergraduate level 1 at a tuition waiver plus NT$8,000 a month, master level 1 at NT$10,000 a month, doctoral level 1 at NT$16,000 a month plus NT$4,000 from the advisor, the undergraduate merit ladder of NT$15,000 for the top 20 per cent and NT$10,000 for the 20 to 40 per cent band with the basic accommodation rate waived, and the Ministry of Education Elite Scholarship at NT$300,000 a year issued as NT$25,000 a month; the international admissions page at admissions.oia.ncku.edu.tw describes the Veritas et Conscientia Scholarship as NT$30,000 a month for full-time PhD students in years 1-4, comprising NT$22,000 from the university and NT$8,000 from the advisor, with tuition, credit fees and the basic on-campus accommodation rate waived, and confirms that applicants need no additional scholarship documents because the award is mailed with the admission letter. CORRECTIONS: the row was titled National Cheng Kung University International Student Scholarship, carried an invented USD 2,125, claimed all three degree levels with no stipend detail and gave a January-February deadline as if the scholarship had a separate window. The real awards pay NT$8,000 to NT$30,000 a month on top of a tuition waiver, they are assessed from the admission file rather than from a separate application, and the top award is doctoral only. award_amount carries the documented maximum monthly stipend of NT$30,000 from the Veritas et Conscientia Scholarship.'
WHERE id = 632;

-- 633 National Tsing Hua University
UPDATE scholarships SET
  title = 'NTHU International Student Scholarship',
  description = 'NTHU publishes its scholarship as two types and the difference decides what a student actually receives. Type A covers full tuition, miscellaneous fees and credit fees and adds a monthly living allowance; Type B covers the same fees with no monthly stipend. The Type A allowance depends on the level: doctoral students receive at least NT$10,000 a month from the Office of Global Affairs, and in the departments that publish a fuller rate the doctoral figure is quoted as NT$20,000 to NT$40,000 a month, part from the Office of Global Affairs and part from the advisor or department; master''s students receive NT$5,000 a month, which is also quoted as NT$60,000 a year, and bachelor''s students receive the same NT$5,000 a month. Housing, insurance and other living costs are not covered, and the award is renewed annually on merit, which means reapplying every year rather than holding the award for the duration. The application is filed through the same online system as the degree application by selecting the NTHU international student scholarship option. The published windows are 1 January to 15 March for the autumn intake and 15 August to 16 October for the spring intake. Four exclusions matter and are easy to miss: recipients of a government scholarship are not eligible, students holding a work visa or an ARC are not eligible, semiconductor research applicants are excluded under one of the departmental pages, and applicants may not apply to programmes in medicine, dentistry or traditional Chinese medicine.',
  requirements = 'Apply for an NTHU international degree programme through the online admission system and select the NTHU international student scholarship option in the same application, since there is no separate form. Be a foreign national who has never held Taiwan nationality, with parents who also hold foreign nationality, and not have studied in Taiwan as an overseas Chinese student. Meet the admission requirements of the chosen undergraduate, master''s or doctoral programme, and note that medicine, dentistry and traditional Chinese medicine are closed to these applicants. File within the published window: 1 January to 15 March for the autumn intake, or 15 August to 16 October for the spring intake. Hold no scholarship from a government agency, since government scholarship recipients are not eligible, and do not hold a work visa or an ARC. Note that the award is renewed annually on merit and must be reapplied for each year, and that semiconductor research applicants are excluded under one departmental page.',
  coverage_type = 'Full Funding', award_basis = 'range', award_amount = 40000, award_currency = 'TWD', award_period = 'month',
  degree_levels = '["Bachelor''s","Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional scholarship with tuition waiver',
  tuition_coverage = 'Type A waives tuition, miscellaneous fees and credit fees and adds a monthly stipend: at least NT$10,000 a month for doctoral students, quoted as NT$20,000 to NT$40,000 in the departments that publish the fuller rate, and NT$5,000 a month for master''s and bachelor''s students. Type B waives the same fees with no stipend. Housing, insurance and living costs are not covered.',
  english_requirements = 'The scholarship sets no separate English score; the English or Chinese requirement of the chosen NTHU programme applies.',
  required_documents = '["NTHU online admission application with the scholarship option selected","Academic transcripts and degree certificates","English or Chinese proficiency evidence as the programme requires","Statement of purpose and letters of recommendation","Proof of nationality and of parents'' nationality where requested","No separate scholarship form"]',
  deadline = '1 January to 15 March for the autumn intake; 15 August to 16 October for the spring intake',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'NTHU opens scholarship applications twice a year with the degree intake: 1 January to 15 March for autumn and 15 August to 16 October for spring, and current students also apply around mid-June and mid-January.',
  website_url = 'https://apply.nthu.edu.tw/en/article/102-nthu-scholarship',
  source_url = 'https://apply.nthu.edu.tw/en/article/102-nthu-scholarship',
  application_url = 'https://oga.site.nthu.edu.tw/p/412-1524-18035.php?Lang=en',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from three National Tsing Hua University own pages read on 2026-10-25: the international scholarship page at apply.nthu.edu.tw states that doctoral students receive NT$20,000 to NT$40,000 a month, that doctoral students in the College of Humanities and Social Sciences or in the International Intercollegiate PhD Program with supervisors from that college receive NT$10,000 a month, that master''s and bachelor''s students receive NT$5,000 a month, that tuition and credit fees are waived, that the scholarship is applied for through the same online system as the degree application by selecting the NTHU international student scholarship option, that applicants and their parents must all hold foreign nationality and never have held Taiwan nationality, that applicants must not have studied in Taiwan as an overseas Chinese student, and that medicine, dentistry and traditional Chinese medicine are closed to applicants; the Office of Global Affairs scholarships page gives the two types - Type A providing full subsidies for tuition, miscellaneous fees and credit fees plus a monthly living allowance, and Type B providing full subsidies for tuition, miscellaneous fees and credit fees only - and quotes the doctoral rate at NT$10,000 a month from the Office of Global Affairs with NT$10,000 to NT$30,000 from the advisor or department; the IMBA scholarship table gives the application periods as 1 January to 15 March for the fall semester and 15 August to 16 October for the spring semester, and the departmental pages add that government scholarship recipients and students with a work visa or ARC are not eligible, that the first month is prorated, that annual reapplication is required, and that semiconductor research applicants are excluded. CORRECTIONS: the row was titled National Tsing Hua University International Student Scholarship, which is correct, but carried an invented USD 2,125, gave a vague January-February deadline and listed the award as if all levels received the same thing. The real structure is Type A against Type B, the stipend runs from NT$5,000 a month at master and bachelor level to NT$40,000 for doctoral students in departments that top up, and renewals are annual. award_amount carries the published upper doctoral monthly rate of NT$40,000.'
WHERE id = 633;

-- 642 National Yang Ming Chiao Tung University
UPDATE scholarships SET
  title = 'NYCU International Student Scholarship',
  description = 'NYCU splits its international award into a monthly stipend and a tuition scholarship, and either can be granted alone or both together, which is why two students at the same university can receive very different packages. The published stipend bands are NT$5,000 to NT$21,000 a month for undergraduates, NT$7,000 to NT$25,000 a month for master''s students and NT$15,000 to NT$30,000 a month for doctoral students, with part funded by the Office of International Affairs and part matched by the college, department or advisor. The tuition scholarship comes in two forms: a full waiver of tuition and credit fees, or tuition and credit fees charged at the local-student rate, with the reduction rate decided by the committee. Incoming students apply with their admission application and the result appears in the admission letter; the award is in principle for one year, and the maximum duration is two years for a master''s and five for a doctorate, with the undergraduate duration set by the department''s regulated study period. Above the standard scheme sits an Elite PhD Scholarship worth NT$33,000 a month, comprising NT$25,000 from the Office of International Affairs and an NT$8,000 matching fund from the advisor, together with a full waiver of tuition and credit fees. Two conditions catch people out: recipients must enrol in at least four Mandarin courses as undergraduates or two as graduate students, and holders of a work visa or an ARC are not eligible. Students who have exhausted the maximum duration and kept an average of 3.0 as undergraduates or 3.5 as graduate students may still apply for the local-student tuition rate.',
  requirements = 'Apply for an NYCU international degree programme and select the scholarship within the admission application, since the result is listed in the admission letter rather than through a separate competition. Hold foreign nationality and meet the admission requirements of the chosen undergraduate, master''s or doctoral programme. Not hold a work visa or an ARC, which excludes an applicant from the award. Enrol in at least four Mandarin courses as an undergraduate or two as a graduate student during your studies, which is a condition of receiving the stipend. Maintain the academic standard for renewal, since the award is granted in principle for one year and the maximum duration is two years at master level and five at doctoral level. Note that the stipend and the tuition scholarship are decided separately and may be granted alone or together, and that the tuition award may be a full waiver or the local-student rate. Current students apply within the published windows, which run from 15 January to 15 March for the fall semester and 15 July to 15 September for the spring.',
  coverage_type = 'Full Funding', award_basis = 'range', award_amount = 30000, award_currency = 'TWD', award_period = 'month',
  degree_levels = '["Bachelor''s","Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional scholarship with tuition waiver',
  tuition_coverage = 'A monthly stipend of NT$5,000 to NT$21,000 for undergraduates, NT$7,000 to NT$25,000 for master''s students and NT$15,000 to NT$30,000 for doctoral students, granted separately from or together with a tuition scholarship that is either a full waiver of tuition and credit fees or the local-student rate. The Elite PhD Scholarship pays NT$33,000 a month plus a full tuition and credit fee waiver.',
  english_requirements = 'The scholarship sets no separate English score; the English requirement of the chosen NYCU programme applies, and evidence such as TOEFL, IELTS or a certificate of English-medium instruction is accepted.',
  required_documents = '["NYCU international admission application with the scholarship selected","Academic transcripts and degree certificates","English proficiency evidence or English-medium instruction certificate","Statement of purpose and letters of recommendation","No work visa or ARC","Enrolment in the required Mandarin courses after arrival"]',
  deadline = 'Applied for with the admission application; current-student windows run from 15 January to 15 March for the fall semester and 15 July to 15 September for the spring',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'New students apply with the admission file and see the result in the admission letter; continuing students apply between 15 January and 15 March for fall and between 15 July and 15 September for spring.',
  website_url = 'https://oia.nycu.edu.tw/oia/en/app/data/view?id=792&module=nycu0012&serno=0f046f83-4147-4ec7-8921-bbaccd8c678f',
  source_url = 'https://dee.nycu.edu.tw/upload_files/news/c5009f1e07fe4c919609f48e80b2f9c3.pdf',
  application_url = 'https://oia.nycu.edu.tw/oia/en/app/data/list?module=nycu0015&id=799',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two National Yang Ming Chiao Tung University own documents read on 2026-10-25: the Office of International Affairs scholarship guidelines PDF hosted by the Department of Electrical Engineering states that awards are divided into monthly stipend and tuition scholarship categories which may be awarded separately or simultaneously, that stipends are paid monthly at NT$5,000 to NT$21,000 for undergraduates, NT$7,000 to NT$25,000 for master students and NT$15,000 to NT$30,000 for doctoral students, that tuition scholarships are either a full waiver of tuition and credit fees or tuition and credit fees charged at the local-student rates with the reduction rate decided by the committee, that the award is in principle approved for one year and may be approved up to two years for master and doctoral students, that the Mandarin course requirement is four courses for undergraduates and two for graduate students, that stipends are paid on the 10th of each month except January and September, and that the Elite PhD Scholarship pays NT$33,000 a month comprising NT$25,000 from the Office of International Affairs and an NT$8,000 matching fund from the advisor with a full waiver of tuition and credit fees; the Office of International Affairs scholarship pages state that incoming students apply along with the admission application, give the current-student windows of 15 January to 15 March for fall and 15 July to 15 September for spring, record that the maximum award duration is two years for master students and five years for doctoral students, and note that students who have reached the maximum duration with an average of 3.0 as undergraduates or 3.5 as graduate students may apply for the local-student tuition rate. CORRECTIONS: the row was titled NYCU International Student Scholarship, which is correct, but carried an invented USD 2,250, claimed a January-February deadline and gave no stipend detail. The real structure is a stipend band by level plus a separately decided tuition scholarship, it is applied for with the admission file rather than in a January-February window, and it carries a Mandarin course obligation. award_amount carries the published upper doctoral monthly rate of NT$30,000.'
WHERE id = 642;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'Yes', funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = true, covers_living_expenses = true, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (211, 'NCKU Distinguished International Student Scholarship (and VCS)', 'Institutional scholarship with tuition waiver', 'Tuition waiver plus NT$8,000 to NT$30,000 a month depending on level and award', 'Assessed from the admission file with no separate application, and the award arrives with the admission letter. Veritas et Conscientia pays NT$30,000 a month to full-time PhD students in years 1-4 with tuition, credit fees and dorm fees waived, by departmental nomination. Holding a Taiwanese government scholarship makes an applicant ineligible.', 'https://oia.ncku.edu.tw/p/404-1032-229890.php?Lang=en'),
  (209, 'NTHU International Student Scholarship', 'Institutional scholarship with tuition waiver', 'Type A tuition waiver plus NT$5,000 to NT$40,000 a month; Type B fees only', 'Applied for through the same system as the degree application: 1 January to 15 March for autumn and 15 August to 16 October for spring. Master and bachelor students receive NT$5,000 a month, doctoral students at least NT$10,000 and up to NT$40,000 in departments that top up. Government scholarship holders and ARC or work visa holders are excluded, and renewals are annual.', 'https://apply.nthu.edu.tw/en/article/102-nthu-scholarship'),
  (245, 'NYCU International Student Scholarship', 'Institutional scholarship with tuition waiver', 'Stipend NT$5,000 to NT$30,000 a month plus a tuition waiver or local-rate tuition', 'Applied for with the admission application and listed in the admission letter. Undergraduates NT$5,000 to 21,000, master students NT$7,000 to 25,000, doctoral students NT$15,000 to 30,000. Recipients must take Mandarin courses and must not hold a work visa or ARC. The Elite PhD award pays NT$33,000 a month.', 'https://oia.nycu.edu.tw/oia/en/app/data/view?id=792&module=nycu0012&serno=0f046f83-4147-4ec7-8921-bbaccd8c678f')
) AS v(id, name, ftype, mx, elig, url)
WHERE u.id = v.id;
